// SPDX-License-Identifier: BSL-1.1
pragma solidity ^0.8.0;

import {UniswapV4BufferHookLiquidityRouteLib as LiquidityRoute} from "contracts/hooks/uniswap/v4/libs/UniswapV4BufferHookLiquidityRouteLib.sol";

import {IERC20} from "@crane/contracts/interfaces/IERC20.sol";
import {IERC20Metadata} from "@crane/contracts/interfaces/IERC20Metadata.sol";
import {BetterSafeERC20 as SafeERC20} from "@crane/contracts/tokens/ERC20/utils/BetterSafeERC20.sol";
import {ERC20Repo} from "@crane/contracts/tokens/ERC20/ERC20Repo.sol";
import {
    toBeforeSwapDelta,
    BeforeSwapDelta
} from "@crane/contracts/protocols/dexes/uniswap/v4/types/BeforeSwapDelta.sol";
import {Currency} from "@crane/contracts/protocols/dexes/uniswap/v4/types/Currency.sol";
import {PoolKey} from "@crane/contracts/protocols/dexes/uniswap/v4/types/PoolKey.sol";
import {IHooks} from "@crane/contracts/protocols/dexes/uniswap/v4/interfaces/IHooks.sol";
import {IPoolManager} from "@crane/contracts/protocols/dexes/uniswap/v4/interfaces/IPoolManager.sol";
import {Hooks} from "@crane/contracts/protocols/dexes/uniswap/v4/libraries/Hooks.sol";
import {LPFeeLibrary} from "@crane/contracts/protocols/dexes/uniswap/v4/libraries/LPFeeLibrary.sol";
import {ModifyLiquidityParams, SwapParams} from
    "@crane/contracts/protocols/dexes/uniswap/v4/types/PoolOperation.sol";
import {BalanceDelta} from "@crane/contracts/protocols/dexes/uniswap/v4/types/BalanceDelta.sol";
import {IStandardExchangeIn} from "@crane/contracts/interfaces/IStandardExchangeIn.sol";
import {IStandardExchangeOut} from "@crane/contracts/interfaces/IStandardExchangeOut.sol";
import {IRateProvider} from
    "@crane/contracts/protocols/dexes/balancer/common/interfaces/IRateProvider.sol";
import {IAllowanceTransfer} from
    "@crane/contracts/interfaces/protocols/utils/permit2/IAllowanceTransfer.sol";
import {IVaultFeeOracleQuery} from "contracts/interfaces/IVaultFeeOracleQuery.sol";
import {DETFDecimalScaleLib} from "contracts/vaults/detf/common/core/DETFDecimalScaleLib.sol";
import {MultiAssetBasicVaultRepo} from "contracts/vaults/basic/MultiAssetBasicVaultRepo.sol";
import {
    IUniswapV4StandardExchangeWeightedBufferHook
} from "contracts/hooks/uniswap/v4/standardExchange/weighted/interfaces/IUniswapV4StandardExchangeWeightedBufferHook.sol";
import {
    UniswapV4StandardExchangeWeightedBufferHookRepo as Repo
} from "contracts/hooks/uniswap/v4/standardExchange/weighted/UniswapV4StandardExchangeWeightedBufferHookRepo.sol";
import {
    UniswapV4StandardExchangeWeightedBufferHookMath as Math
} from "contracts/hooks/uniswap/v4/standardExchange/weighted/UniswapV4StandardExchangeWeightedBufferHookMath.sol";
import {
    UniswapV4StandardExchangeWeightedBufferHookPairPoolLib as PairPoolLib
} from "contracts/hooks/uniswap/v4/standardExchange/weighted/UniswapV4StandardExchangeWeightedBufferHookPairPoolLib.sol";

/**
 * @title UniswapV4StandardExchangeWeightedBufferHookTarget
 * @notice Product logic: dual-scale weighted book, SE buffer-last LP, rated V4/SE swaps, MultiAssetLiquidity.
 * @dev No BaseHook / DeltaResolver inheritance. LP via ERC20Repo; inventory = face | live SE shares.
 */
import {
    UniswapV4StandardExchangeWeightedBufferHookHooksTarget
} from "contracts/hooks/uniswap/v4/standardExchange/weighted/UniswapV4StandardExchangeWeightedBufferHookHooksTarget.sol";
import {MultiStepOwnableRepo} from "@crane/contracts/access/ERC8023/MultiStepOwnableRepo.sol";
import {IMultiStepOwnable} from "@crane/contracts/interfaces/IMultiStepOwnable.sol";
import {IDetfReserveQuote} from "contracts/hooks/uniswap/v4/interfaces/IDetfReserveQuote.sol";

/**
 * @title UniswapV4StandardExchangeWeightedBufferHookSeTarget
 * @notice Standard Exchange swaps and native LP join/exit routes.
 */
abstract contract UniswapV4StandardExchangeWeightedBufferHookSeTarget is
    UniswapV4StandardExchangeWeightedBufferHookHooksTarget,
    IStandardExchangeIn,
    IStandardExchangeOut
{
    using SafeERC20 for IERC20;

/* ---------------------------------------------------------------------- */
    /*                         Standard Exchange swap and liquidity routes                        */
    /* ---------------------------------------------------------------------- */

    function previewExchangeIn(IERC20 tokenIn, uint256 amountIn, IERC20 tokenOut)
        external
        view
        returns (uint256 amountOut)
    {
        if (LiquidityRoute.isLiquidityRoute(tokenIn, tokenOut)) {
            return LiquidityRoute.previewInWithSe(tokenIn, amountIn, tokenOut, _liquiditySePair(tokenIn, tokenOut));
        }
        return _previewSwapExactIn(address(tokenIn), address(tokenOut), amountIn);
    }

    function exchangeIn(
        IERC20 tokenIn,
        uint256 amountIn,
        IERC20 tokenOut,
        uint256 minAmountOut,
        address recipient,
        bool pretransferred,
        uint256 deadline
    ) external returns (uint256 amountOut) {
        if (LiquidityRoute.isLiquidityRoute(tokenIn, tokenOut)) {
            address pair_ = _liquiditySePair(tokenIn, tokenOut);
            return LiquidityRoute.exchangeInWithSe(tokenIn, amountIn, tokenOut, minAmountOut, recipient, pretransferred, deadline, pair_);
        }
        return _swapExchangeIn(tokenIn, amountIn, tokenOut, minAmountOut, recipient, pretransferred, deadline);
    }

    function _swapExchangeIn(
        IERC20 tokenIn,
        uint256 amountIn,
        IERC20 tokenOut,
        uint256 minAmountOut,
        address recipient,
        bool pretransferred,
        uint256 deadline
    ) internal nonReentrant returns (uint256 amountOut) {
        _requireDeadline(deadline);
        if (amountIn == 0) revert ZeroAmount();
        if (recipient == address(0)) revert ZeroAddress();
        address tin = address(tokenIn);
        address tout = address(tokenOut);
        if (tin == tout) revert InvalidRoute(tin, tout);
        _tokenIndex(tin);
        _tokenIndex(tout);

        // L-GAPS-11 / ISecurePullErrors: pretransfer credits only in-window delta (I1/I3).
        _securePull(IERC20(tin), amountIn, pretransferred);

        amountOut = _previewSwapExactIn(tin, tout, amountIn);
        if (amountOut < minAmountOut) revert Slippage();

        uint8 j = _tokenIndex(tout);
        uint8 i = _tokenIndex(tin);
        Repo.Layout storage l = Repo._layout();
        if (l.standardExchanges[j] != address(0)) {
            _unwrapExactTokenOut(j, amountOut, recipient);
        } else {
            if (amountOut >= l.rawReserves[j]) revert WouldZeroReserve();
            l.rawReserves[j] -= amountOut;
            IERC20(tout).safeTransfer(recipient, amountOut);
        }
        // buffer-last in
        if (l.standardExchanges[i] != address(0)) {
            _bufferToken(i, amountIn);
        } else {
            l.rawReserves[i] += amountIn;
        }
        _syncVaultReserves();
    }

    function previewExchangeOut(IERC20 tokenIn, IERC20 tokenOut, uint256 amountOut)
        external
        view
        returns (uint256 amountIn)
    {
        if (LiquidityRoute.isLiquidityRoute(tokenIn, tokenOut)) {
            if (_liquiditySePair(tokenIn, tokenOut) != address(0)) revert ExchangeOutNotAvailable();
            return LiquidityRoute.previewOut(tokenIn, tokenOut, amountOut);
        }
        return _previewSwapExactOut(address(tokenIn), address(tokenOut), amountOut);
    }

    function exchangeOut(
        IERC20 tokenIn,
        uint256 maxAmountIn,
        IERC20 tokenOut,
        uint256 amountOut,
        address recipient,
        bool pretransferred,
        uint256 deadline
    ) external returns (uint256 amountIn) {
        if (LiquidityRoute.isLiquidityRoute(tokenIn, tokenOut)) {
            if (_liquiditySePair(tokenIn, tokenOut) != address(0)) revert ExchangeOutNotAvailable();
            return LiquidityRoute.exchangeOut(tokenIn, maxAmountIn, tokenOut, amountOut, recipient, pretransferred, deadline);
        }
        return _swapExchangeOut(tokenIn, maxAmountIn, tokenOut, amountOut, recipient, pretransferred, deadline);
    }

    function _swapExchangeOut(
        IERC20 tokenIn,
        uint256 maxAmountIn,
        IERC20 tokenOut,
        uint256 amountOut,
        address recipient,
        bool pretransferred,
        uint256 deadline
    ) internal nonReentrant returns (uint256 amountIn) {
        _requireDeadline(deadline);
        if (amountOut == 0) revert ZeroAmount();
        if (recipient == address(0)) revert ZeroAddress();
        address tin = address(tokenIn);
        address tout = address(tokenOut);
        amountIn = _previewSwapExactOut(tin, tout, amountOut);
        if (amountIn > maxAmountIn) revert Slippage();

        // L-GAPS-11: delta-gate claimed amountIn (no absolute free inventory credit).
        _securePull(IERC20(tin), amountIn, pretransferred);

        uint8 j = _tokenIndex(tout);
        uint8 ii = _tokenIndex(tin);
        Repo.Layout storage l = Repo._layout();
        if (l.standardExchanges[j] != address(0)) {
            _unwrapExactTokenOut(j, amountOut, recipient);
        } else {
            if (amountOut >= l.rawReserves[j]) revert WouldZeroReserve();
            l.rawReserves[j] -= amountOut;
            IERC20(tout).safeTransfer(recipient, amountOut);
        }
        if (l.standardExchanges[ii] != address(0)) {
            _bufferToken(ii, amountIn);
        } else {
            l.rawReserves[ii] += amountIn;
        }
        _syncVaultReserves();
    }

    /// @notice D89: owner exact-in; internal book settlement (no nested PoolManager.unlock).
    function ownerSwapExactIn(
        address tokenIn,
        address tokenOut,
        uint256 amountIn,
        uint256 minAmountOut,
        uint256 deadline
    ) external nonReentrant returns (uint256 amountOut) {
        _onlyHookOwner();
        _requireDeadline(deadline);
        if (amountIn == 0) revert ZeroAmount();
        if (tokenIn == tokenOut) revert InvalidRoute(tokenIn, tokenOut);
        _tokenIndex(tokenIn);
        _tokenIndex(tokenOut);
        amountOut = _previewSwapExactIn(tokenIn, tokenOut, amountIn);
        if (amountOut < minAmountOut) revert Slippage();
        _securePull(IERC20(tokenIn), amountIn, false);
        _payOwnerSwap(tokenIn, tokenOut, amountIn, amountOut);
    }

    /// @notice D89: owner exact-out; internal book settlement (no nested PoolManager.unlock).
    function ownerSwapExactOut(
        address tokenIn,
        address tokenOut,
        uint256 amountOut,
        uint256 maxAmountIn,
        uint256 deadline
    ) external nonReentrant returns (uint256 amountIn) {
        _onlyHookOwner();
        _requireDeadline(deadline);
        if (amountOut == 0) revert ZeroAmount();
        if (tokenIn == tokenOut) revert InvalidRoute(tokenIn, tokenOut);
        amountIn = _previewSwapExactOut(tokenIn, tokenOut, amountOut);
        if (amountIn > maxAmountIn) revert Slippage();
        _securePull(IERC20(tokenIn), amountIn, false);
        _payOwnerSwap(tokenIn, tokenOut, amountIn, amountOut);
    }

    function _onlyHookOwner() private view {
        if (msg.sender != MultiStepOwnableRepo._owner()) {
            revert IMultiStepOwnable.NotOwner(msg.sender);
        }
    }

    function _payOwnerSwap(address tokenIn, address tokenOut, uint256 amountIn, uint256 amountOut) private {
        uint8 j = _tokenIndex(tokenOut);
        uint8 i = _tokenIndex(tokenIn);
        Repo.Layout storage l = Repo._layout();
        if (l.standardExchanges[j] != address(0)) {
            _unwrapExactTokenOut(j, amountOut, msg.sender);
        } else {
            if (amountOut >= l.rawReserves[j]) revert WouldZeroReserve();
            l.rawReserves[j] -= amountOut;
            IERC20(tokenOut).safeTransfer(msg.sender, amountOut);
        }
        if (l.standardExchanges[i] != address(0)) {
            _bufferToken(i, amountIn);
        } else {
            l.rawReserves[i] += amountIn;
        }
        _syncVaultReserves();
    }

    function _liquiditySePair(IERC20 in_, IERC20 out_) private view returns (address) {
        address edge_ = address(in_) == address(this) ? address(out_) : address(in_);
        Repo.Layout storage l_ = Repo._layout();
        for (uint256 i_; i_ < l_.numTokens; ++i_) {
            if (edge_ != address(0) && edge_ == l_.standardExchanges[i_]) return l_.tokens[i_];
        }
        return address(0);
    }

}

// SPDX-License-Identifier: BSL-1.1
pragma solidity ^0.8.0;

import {IPoolManager} from "@crane/contracts/protocols/dexes/uniswap/v4/interfaces/IPoolManager.sol";
import {IVaultFeeOracleQuery} from "contracts/interfaces/IVaultFeeOracleQuery.sol";
import {IUniswapV4SeBufferHook} from "contracts/hooks/uniswap/v4/interfaces/IUniswapV4SeBufferHook.sol";
import {IDetfReserveQuote} from "contracts/hooks/uniswap/v4/interfaces/IDetfReserveQuote.sol";

/**
 * @title IUniswapV4StandardExchangeWeightedBufferHook
 * @notice Public product surface: n-asset (2–8) Balancer weighted book with ≥1 SE buffer legs.
 * @dev DETF-facing ABI is IUniswapV4SeBufferHook + IDetfReserveQuote.
 *      Family joinUnbalanced(uint256[]) / depositSingle / *Flexible remain as wrappers.
 *      LP ERC-20 + EIP-2612 + vault discovery via shared diamond facets (not redeclared here).
 */
interface IUniswapV4StandardExchangeWeightedBufferHook is IUniswapV4SeBufferHook, IDetfReserveQuote {
    enum KLastMode {
        FullProduct,
        PartialInterim
    }

    event Join(
        address indexed sender,
        address indexed to,
        uint256 shares,
        int256[] deltas,
        uint256 protocolSharesMinted
    );
    event Exit(
        address indexed sender,
        address indexed to,
        uint256 shares,
        int256[] deltas,
        uint256 protocolSharesMinted
    );
    event DepositSingle(
        address indexed sender,
        address indexed to,
        address token,
        uint256 amountIn,
        uint256 shares,
        uint256 protocolSharesMinted
    );
    event WithdrawSingle(
        address indexed sender,
        address indexed to,
        address token,
        uint256 amountOut,
        uint256 shares,
        uint256 protocolSharesMinted
    );
    event WithdrawSingleExactOut(
        address indexed sender,
        address indexed to,
        address token,
        uint256 amountOut,
        uint256 sharesBurned,
        uint256 protocolSharesMinted
    );
    event ProtocolFeeMinted(address indexed feeTo, uint256 shares);
    event PairPoolsEnsured(address indexed hook, uint256 doorsEnsured);

    /// @notice B6 proportional join with per-leg pair vs SE-share units (`amountIsSeShare`).
    event JoinFlexible(
        address indexed sender,
        address indexed to,
        uint256 shares,
        uint256[] amounts,
        bool[] amountIsSeShare,
        uint256[] usedAmounts,
        uint256 protocolSharesMinted
    );

    /// @notice B6 proportional exit paying pair and/or SE shares per leg (`receiveSeShare`).
    event ExitFlexible(
        address indexed sender,
        address indexed to,
        uint256 shares,
        bool[] receiveSeShare,
        uint256[] amounts,
        uint256 protocolSharesMinted
    );

    event DepositSingleFlexible(
        address indexed sender,
        address indexed to,
        address token,
        uint256 amountIn,
        bool amountIsSeShare,
        uint256 shares,
        uint256 protocolSharesMinted
    );

    event WithdrawSingleFlexible(
        address indexed sender,
        address indexed to,
        address token,
        uint256 amountOut,
        bool receiveSeShare,
        uint256 shares,
        uint256 protocolSharesMinted
    );

    /* ------------------------------- Binding -------------------------------- */

    function poolManager() external view returns (IPoolManager);
    function feeOracle() external view returns (IVaultFeeOracleQuery);
    function permit2() external view returns (address);
    function numTokens() external view returns (uint8);
    function tokens() external view returns (address[] memory);
    function token(uint256 index) external view returns (address);
    function getNormalizedWeights() external view returns (uint256[] memory);
    function weight(uint256 index) external view returns (uint256);
    function standardExchange(uint256 index) external view returns (address);
    function rateProvider(uint256 index) external view returns (address);
    function isBuffered(uint256 index) external view returns (bool);

    /* --------------------------- Inventory / rated -------------------------- */

    function nativeReserve(uint256 index) external view returns (uint256);
    function nativeReserves() external view returns (uint256[] memory);
    function ratedBalance(uint256 index) external view returns (uint256);
    function ratedBalances() external view returns (uint256[] memory);
    function seBalance(uint256 index) external view returns (uint256);
    function seClaim(uint256 index) external view returns (uint256);
    function invScale(uint256 index) external view returns (uint256);
    function ratedScale(uint256 index) external view returns (uint256);

    /* -------------------------------- Fees ---------------------------------- */

    function dexSwapFee() external view returns (uint256);
    function usageFee() external view returns (uint256);
    function feeTo() external view returns (address);
    function kLast() external view returns (uint256);
    function kLastMode() external view returns (KLastMode);
    function isFullBook() external view returns (bool);

    /* ----------------------------- Pair doors ------------------------------- */

    function ensurePairPools() external returns (uint256 doorsEnsured);
    function pairDoorCount() external view returns (uint256);

    /* ------------------------------ Previews -------------------------------- */

    function previewSwapExactIn(address tokenIn, address tokenOut, uint256 amountIn)
        external
        view
        returns (uint256 amountOut);

    function previewSwapExactOut(address tokenIn, address tokenOut, uint256 amountOut)
        external
        view
        returns (uint256 amountIn);

    /// @notice D89 / D30: owner exact-in on the weighted book. Internal settlement (no nested unlock).
    function ownerSwapExactIn(
        address tokenIn,
        address tokenOut,
        uint256 amountIn,
        uint256 minAmountOut,
        uint256 deadline
    ) external returns (uint256 amountOut);

    /// @notice D89 / D30: owner exact-out on the weighted book. Internal settlement (no nested unlock).
    function ownerSwapExactOut(
        address tokenIn,
        address tokenOut,
        uint256 amountOut,
        uint256 maxAmountIn,
        uint256 deadline
    ) external returns (uint256 amountIn);

    function previewJoinProportional(uint256[] calldata amounts)
        external
        view
        returns (uint256 shares, uint256[] memory usedAmounts);

    function previewJoinSingleAssetExactIn(address tokenIn, uint256 amountIn)
        external
        view
        returns (uint256 shares);

    function previewJoinSingleAssetExactOut(address tokenIn, uint256 sharesOut)
        external
        view
        returns (uint256 amountIn);

    function previewJoinUnbalanced(uint256[] calldata amounts) external view returns (uint256 shares);

    function previewExitProportional(uint256 shares) external view returns (uint256[] memory amounts);

    function previewExitSingleAssetExactBptIn(address tokenOut, uint256 sharesIn)
        external
        view
        returns (uint256 amountOut);

    function previewExitSingleAssetExactTokenOut(address tokenOut, uint256 amountOut)
        external
        view
        returns (uint256 sharesIn);

    function previewDepositSingle(address tokenIn, uint256 amountIn)
        external
        view
        returns (uint256 shares);

    function previewWithdrawSingle(address tokenOut, uint256 sharesIn)
        external
        view
        returns (uint256 amountOut);

    function previewWithdrawSingleExactOut(address tokenOut, uint256 amountOut)
        external
        view
        returns (uint256 sharesIn);

    /// @notice B6: proportional join preview; `amountIsSeShare[i]` selects SE vault share vs pair for leg i.
    function previewJoinProportionalFlexible(uint256[] calldata amounts, bool[] calldata amountIsSeShare)
        external
        view
        returns (uint256 shares, uint256[] memory usedAmounts);

    function previewExitProportionalFlexible(uint256 shares, bool[] calldata receiveSeShare)
        external
        view
        returns (uint256[] memory amounts);

    function previewJoinSingleAssetExactInFlexible(address tokenIn, uint256 amountIn, bool amountIsSeShare)
        external
        view
        returns (uint256 shares);

    function previewDepositSingleFlexible(address tokenIn, uint256 amountIn, bool amountIsSeShare)
        external
        view
        returns (uint256 shares);

    function previewExitSingleAssetExactBptInFlexible(address tokenOut, uint256 sharesIn, bool receiveSeShare)
        external
        view
        returns (uint256 amountOut);

    function previewWithdrawSingleFlexible(address tokenOut, uint256 sharesIn, bool receiveSeShare)
        external
        view
        returns (uint256 amountOut);

    /* ------------------------------ Liquidity ------------------------------- */

    function joinProportional(
        uint256[] calldata amounts,
        address to,
        uint256 sharesMin,
        uint256 deadline
    ) external returns (uint256 shares, uint256[] memory usedAmounts);

    function joinSingleAssetExactIn(
        address tokenIn,
        uint256 amountIn,
        address to,
        uint256 sharesMin,
        uint256 deadline
    ) external returns (uint256 shares);

    function joinSingleAssetExactOut(
        address tokenIn,
        uint256 sharesOut,
        address to,
        uint256 amountInMax,
        uint256 deadline
    ) external returns (uint256 amountIn);

    function joinUnbalanced(uint256[] calldata amounts, address to, uint256 sharesMin, uint256 deadline)
        external
        returns (uint256 shares);

    function exitProportional(uint256 shares, address to, uint256[] calldata amountsMin, uint256 deadline)
        external
        returns (uint256[] memory amounts);

    function exitSingleAssetExactBptIn(
        address tokenOut,
        uint256 sharesIn,
        address to,
        uint256 amountOutMin,
        uint256 deadline
    ) external returns (uint256 amountOut);

    function exitSingleAssetExactTokenOut(
        address tokenOut,
        uint256 amountOut,
        address to,
        uint256 sharesInMax,
        uint256 deadline
    ) external returns (uint256 sharesIn);

    function depositSingle(
        address tokenIn,
        uint256 amountIn,
        address to,
        uint256 sharesMin,
        uint256 deadline
    ) external returns (uint256 shares);

    function withdrawSingle(
        address tokenOut,
        uint256 sharesIn,
        address to,
        uint256 amountOutMin,
        uint256 deadline
    ) external returns (uint256 amountOut);

    function withdrawSingleExactOut(
        address tokenOut,
        uint256 amountOut,
        address to,
        uint256 sharesInMax,
        uint256 deadline
    ) external returns (uint256 sharesIn);

    /* ------------------------- B6: SE-share flexible LP ------------------------- */

    /// @notice B6 proportional join: per leg pair token and/or SE vault share (buffered legs only).
    function joinProportionalFlexible(
        uint256[] calldata amounts,
        bool[] calldata amountIsSeShare,
        address to,
        uint256 sharesMin,
        uint256 deadline
    ) external returns (uint256 shares, uint256[] memory usedAmounts);

    /// @notice B6 proportional exit: pay pair tokens and/or SE vault shares per buffered leg.
    function exitProportionalFlexible(
        uint256 shares,
        address to,
        bool[] calldata receiveSeShare,
        uint256[] calldata amountsMin,
        uint256 deadline
    ) external returns (uint256[] memory amounts);

    function joinSingleAssetExactInFlexible(
        address tokenIn,
        uint256 amountIn,
        bool amountIsSeShare,
        address to,
        uint256 sharesMin,
        uint256 deadline
    ) external returns (uint256 shares);

    function depositSingleFlexible(
        address tokenIn,
        uint256 amountIn,
        bool amountIsSeShare,
        address to,
        uint256 sharesMin,
        uint256 deadline
    ) external returns (uint256 shares);

    function exitSingleAssetExactBptInFlexible(
        address tokenOut,
        uint256 sharesIn,
        bool receiveSeShare,
        address to,
        uint256 amountOutMin,
        uint256 deadline
    ) external returns (uint256 amountOut);

    function withdrawSingleFlexible(
        address tokenOut,
        uint256 sharesIn,
        bool receiveSeShare,
        address to,
        uint256 amountOutMin,
        uint256 deadline
    ) external returns (uint256 amountOut);
}

