    /**
     * @dev Converts a uint256 to a string.
     * @param value The value to convert.
     * @return result The converted value.
     */
    function _toString(uint256 value) internal pure returns (string memory result) {
        if (value == 0) {
            return "0";
        }

        uint256 temp = value;
        uint256 digits;

        while (temp != 0) {
            digits++;
            temp /= 10;
